{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "credible_gap",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0003",
          "reason": "Inherited TPNW ratification is state-level baseline, not a Prayut-specific 2022 existential-risk choice."
        },
        {
          "evidence_id": "E0006",
          "reason": "IAEA safeguards status is institutional context and should not be read as direct ruler conduct."
        },
        {
          "evidence_id": "E0009",
          "reason": "SEANWFZ obligations are long-standing regional law; use only as inherited posture, not ruler action."
        },
        {
          "evidence_id": "E0012",
          "reason": "Global arsenal totals are structural context only and do not show Prayut-attributed restraint or risk management."
        }
      ],
      "material_gaps": [
        {
          "gap": "No direct 2022 ruler-attributed existential-risk choice, escalation, or crisis-management episode is shown.",
          "lenses": ["1B.1", "1B.2", "1B.8", "1B.9", "1B.10"],
          "best_source_or_query_direction": "Thai cabinet, defense, and foreign-ministry records; IAEA/CTBTO/UNODA meeting records; Reuters/AP on any 2022 nuclear, WMD, cyber, bio, or other catastrophic-risk decision.",
          "why_it_matters": "Without a direct choice, the dossier can only establish limited exposure and inherited posture, not ruler responsibility."
        },
        {
          "gap": "Command-and-control, custody, and safety-governance evidence tied specifically to Prayut remains thin.",
          "lenses": ["1B.3", "1B.7"],
          "best_source_or_query_direction": "Thai defense and OAP records, IAEA country files, and contemporaneous reporting on any nuclear-safety or dual-use oversight decision in 2022.",
          "why_it_matters": "This is needed to separate inherited compliance from ruler-level stewardship."
        }
      ],
      "reason": "The package is fair about Thailand's limited nuclear exposure and inherited treaty posture, but almost all retained material is baseline or institutional context rather than a 2022 Prayut-specific risk-bearing choice. That supports a null-style limited-exposure review, not a stronger conduct conclusion."
    },
    {
      "chapter_id": "2B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0014",
          "reason": "This is an official foreign-ministry position on Ukraine, so it should be treated as state diplomacy under Prayut rather than personal PM conduct."
        },
        {
          "evidence_id": "E0016",
          "reason": "Myanmar spillover diplomacy is relevant, but the evidence is ministry-level posture rather than direct Prayut action."
        },
        {
          "evidence_id": "E0018",
          "reason": "UNGA speech by the foreign minister is institutional diplomacy, not a personal PM order or security decision."
        },
        {
          "evidence_id": "E0019",
          "reason": "The Myanmar consultation is a hosting action and should be framed as foreign-policy machinery, not personal conduct."
        },
        {
          "evidence_id": "E0021",
          "reason": "This is UN-delegation explanation-of-vote material; keep it as government posture, not direct ruler attribution."
        },
        {
          "evidence_id": "E0023",
          "reason": "The abstention is a state position on Ukraine accountability, not evidence of a Prayut-led military or coercive choice."
        }
      ],
      "material_gaps": [
        {
          "gap": "PM-level attribution for 2022 international-security choices is still thin; most evidence is ministry or delegation posture.",
          "lenses": ["2B.1", "2B.6", "2B.7", "2B.10"],
          "best_source_or_query_direction": "Prayut speeches, cabinet minutes, Thai MFA cables/briefings, and Reuters/AP on any direct PM-level instruction or public commitment.",
          "why_it_matters": "The package can show Thai diplomacy, but not yet a clean ruler-level choice chain."
        },
        {
          "gap": "The Myanmar and Ukraine material does not yet show concrete peace or accountability outcomes attributable to Prayut.",
          "lenses": ["2B.5", "2B.7", "2B.9"],
          "best_source_or_query_direction": "ASEAN records, border-defense directives, humanitarian access reporting, and follow-up independent analysis of the 2022 consultations and votes.",
          "why_it_matters": "This would separate rhetoric and posture from actual conflict management."
        }
      ],
      "reason": "The evidence fairly captures Thailand's diplomatic posture on Ukraine and Myanmar, including contrary views and hedging, but the attribution chain is mostly government-level rather than Prayut personally. That is enough to keep the chapter alive, not enough to fully close the ruler-conduct question."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0034",
          "reason": "This is a reform milestone; it should not be double-counted as proof that enforcement already improved."
        },
        {
          "evidence_id": "E0035",
          "reason": "Procedural coverage of the same anti-torture law should be treated as corroboration, not a separate event."
        },
        {
          "evidence_id": "E0036",
          "reason": "APEC crackdown coverage needs to be kept as one event family, not multiple independent incidents."
        },
        {
          "evidence_id": "E0038",
          "reason": "This duplicates the same APEC protest episode from another publisher family and should only corroborate the core event."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct chain-of-command evidence for the APEC crackdown and the deep-south emergency regime remains limited.",
          "lenses": ["3B.2", "3B.5", "3B.9"],
          "best_source_or_query_direction": "Police operational orders, NHRC findings, cabinet or parliamentary records, and any court or inquiry documents on the 2022 protest policing and southern security regime.",
          "why_it_matters": "It would distinguish supervisory responsibility from broader regime-level repression."
        },
        {
          "gap": "The torture/disappearance law is an important reform, but year-end enforcement evidence is still weak.",
          "lenses": ["3B.1", "3B.4"],
          "best_source_or_query_direction": "Ministry of Justice implementation notices, prosecution records, and NHRC follow-up on the 2022 act.",
          "why_it_matters": "Without enforcement evidence, the reform remains a partial mitigation rather than a full remedy."
        }
      ],
      "reason": "This is the strongest chapter in the package: it preserves severe harms, acknowledges reform, and keeps contradictory evidence visible. The main weakness is attribution depth, not fairness or balance."
    },
    {
      "chapter_id": "4B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0001",
          "reason": "This is authority-timeline context from the term-limit suspension, not direct evidence of political freedom or authoritarian rule."
        },
        {
          "evidence_id": "E0002",
          "reason": "The court ruling about continued office is a legal-status reference, not evidence of democratic openness by itself."
        },
        {
          "evidence_id": "E0041",
          "reason": "This is an opposition allegation about electoral-system manipulation; it should not be treated as established manipulation without corroboration."
        },
        {
          "evidence_id": "E0048",
          "reason": "The Pegasus report is relevant background, but the infections predate 2022 and the operator is not conclusively identified."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence on the sponsors and mechanism of the election-system change is still thin.",
          "lenses": ["4B.2", "4B.8"],
          "best_source_or_query_direction": "Parliamentary records, constitutional filings, named sponsors, and court documents on the election-system dispute.",
          "why_it_matters": "It would separate proven ruler-linked manipulation from broader coalition conflict."
        },
        {
          "gap": "4B.4 and 4B.7 remain under-evidenced relative to the stronger protest, media, and term-limit material.",
          "lenses": ["4B.4", "4B.7", "4B.9"],
          "best_source_or_query_direction": "Court, audit, and local-government records, plus rights and press-freedom monitoring focused on minorities, women, and excluded groups.",
          "why_it_matters": "The chapter still leans heavily on coercive-environment evidence rather than direct institutional-strength or equality evidence."
        }
      ],
      "reason": "The package does a credible job on contestation, media chill, surveillance, and term-limit politics, but some key items are indirect or pre-2022 context and the weakest lenses remain weak. It is usable, but still needs tighter ruler-specific attribution."
    },
    {
      "chapter_id": "5B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0052",
          "reason": "IMF macro assessment is useful context, but it is not direct proof of Prayut's personal economic competence."
        },
        {
          "evidence_id": "E0054",
          "reason": "This is IMF policy advice and should not be treated as evidence that Prayut implemented the recommended path."
        },
        {
          "evidence_id": "E0058",
          "reason": "World Bank inequality metrics are structural baseline context, not direct ruler action."
        },
        {
          "evidence_id": "E0059",
          "reason": "The private-sector diagnostic is a background diagnosis of constraints, not evidence of execution or non-execution by Prayut."
        },
        {
          "evidence_id": "E0061",
          "reason": "Monetary-policy decisions are only partly attributable to the cabinet and should not be over-personalized."
        },
        {
          "evidence_id": "E0067",
          "reason": "This BOI release is promotional and retrospective; it should be balanced against weaker and more independent evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "Budget intent and macro recovery are better evidenced than actual implementation and take-up.",
          "lenses": ["5B.1", "5B.6", "5B.9"],
          "best_source_or_query_direction": "Budget execution reports, ministry audits, household surveys, and independent program evaluations for 2022 spending and subsidies.",
          "why_it_matters": "Announcements and forecasts do not establish delivered competence."
        },
        {
          "gap": "Evidence on appointments, anti-capture, and mistake-correction is still weak.",
          "lenses": ["5B.2", "5B.5", "5B.7"],
          "best_source_or_query_direction": "Cabinet personnel records, procurement/corruption probes, and documentation of policy reversal or correction.",
          "why_it_matters": "This would separate genuine stewardship from favorable macro tailwinds and promotional claims."
        }
      ],
      "reason": "The package is broad and plausibly balanced, but it mixes direct policy actions with IMF/World Bank advice, forecasts, and post-hoc diagnostics. That makes it informative, yet still too weak on ruler-specific execution and anti-capture proof."
    },
    {
      "chapter_id": "6B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0076",
          "reason": "Structural rural poverty diagnostics are baseline context, not direct proof of Prayut's welfare performance."
        },
        {
          "evidence_id": "E0078",
          "reason": "This is pandemic damage and country-level context; it should not be treated as direct ruler delivery evidence."
        },
        {
          "evidence_id": "E0079",
          "reason": "The mental-health report is important, but it is mostly system-level context rather than Prayut-specific action or failure."
        },
        {
          "evidence_id": "E0080",
          "reason": "The MICS survey measures 2022 conditions, but it is not a clean measure of Prayut's personal contribution."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct service-delivery, take-up, and quality evidence is thin outside budget allocations and national surveys.",
          "lenses": ["6B.2", "6B.4", "6B.5"],
          "best_source_or_query_direction": "Ministry performance data, provincial uptake figures, and independent program evaluations on health, education, child grant, and social-protection delivery.",
          "why_it_matters": "It would distinguish funded intent from actual welfare improvement."
        },
        {
          "gap": "Ruler-specific causal attribution for rural, child, and mental-health outcomes remains weak.",
          "lenses": ["6B.3", "6B.6", "6B.10"],
          "best_source_or_query_direction": "Longitudinal household panels, province-level administrative data, and implementation records for 2022 social programs.",
          "why_it_matters": "Current evidence mostly shows the social environment, not Prayut's measurable contribution."
        }
      ],
      "reason": "The dossier is fair on budgets, vulnerability, and mixed outcomes, but the strongest items are still country-level conditions and survey results rather than direct delivery evidence. It is usable, though not yet cleanly attributable."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0082",
          "reason": "Opposition allegations about graft and constitutional violations are context only unless independently verified."
        },
        {
          "evidence_id": "E0085",
          "reason": "This repeats the same allegation family and should not be used as independent proof."
        },
        {
          "evidence_id": "E0086",
          "reason": "Surviving a no-confidence vote is political context, not evidence of personal honesty or dishonesty."
        },
        {
          "evidence_id": "E0095",
          "reason": "Older oath-omission reporting is background, not target-year conduct, and should not be used as 2022 proof."
        },
        {
          "evidence_id": "E0096",
          "reason": "The transparency loophole shows an accountability gap, but not proven personal enrichment or concealment by itself."
        },
        {
          "evidence_id": "E0097",
          "reason": "This is older cabinet-formation criticism and should be treated as background, not 2022 integrity evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "No independent 2022 finding of personal lying, self-dealing, or concealed conflict of interest is shown.",
          "lenses": ["7B.1", "7B.2", "7B.4", "7B.6"],
          "best_source_or_query_direction": "NACC files, court judgments, audit/inquiry records, asset declarations, procurement records, and investigative reporting tied to Prayut personally.",
          "why_it_matters": "Personal-nexus evidence is the core requirement for this chapter, and it is missing."
        },
        {
          "gap": "The package relies too much on allegations, self-defense, and broader regime context.",
          "lenses": ["7B.7", "7B.9", "7B.10"],
          "best_source_or_query_direction": "Primary documentary trail on Prayut's own statements, corrections, assets, and any direct benefit or obstruction after notice.",
          "why_it_matters": "Without that, the dossier risks personalizing authoritarianism without proving personal dishonesty."
        }
      ],
      "reason": "This chapter is the weakest and most contamination-prone in the package. It leans heavily on allegations, denials, coalition maneuvering, and background scandals, with little independent 2022 evidence of personal dishonesty or self-enrichment. That is a manual-review issue, not just a follow-up."
    },
    {
      "chapter_id": "8B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "The program basis is only partly explicit; some objectives are inferred from budgets and coalition moves rather than a single frozen program statement.",
          "lenses": ["8B.1", "8B.8", "8B.10"],
          "best_source_or_query_direction": "Manifestos, cabinet agenda documents, official program memoranda, and repeated direct speeches from 2022.",
          "why_it_matters": "Execution cannot be judged cleanly without a stable baseline program."
        },
        {
          "gap": "Outcome evidence is sectoral and mixed, and external reopening effects remain hard to separate from ruler skill.",
          "lenses": ["8B.7", "8B.9", "8B.10"],
          "best_source_or_query_direction": "Independent sector evaluations, subnational administrative outcomes, and lagged indicators for investment, tourism, and fiscal measures.",
          "why_it_matters": "This would distinguish competence from favorable macro tailwinds and partial rebounds."
        }
      ],
      "reason": "The package gives a coherent program-to-implementation arc with good budget, appointment, and sectoral-policy evidence, but its outcome evidence is still mixed and partly external. It is serviceable, but not yet fully pinned down."
    }
  ]
}
